import org.junit.runner.RunWith

/**
 * `RUN_D8` — the official v5 device evaluation, against the real model, exactly once.
 *
 * ## What makes this the run of record
 *
 *  - It is its own class. A smoke run cannot reach this code, and this code cannot be capped:
 *    passing `ryeongScenarioLimit` makes it fail before the first turn rather than quietly produce a
 *    short result carrying the official identifier.
 *  - It takes the invocation with an atomic file creation. A second execution — deliberate or by a
 *    retry loop — is refused and recorded in a refusal log, and the first run's evidence is never
 *    opened for writing.
 *  - Turn records are streamed to `raw_turns.jsonl.partial`, flushed and synced per turn, and
 *    promoted to their final name only after the 139 / 386 / 22 inventory and the depth census match
 *    exactly. A run that dies leaves its partial and a status that says it is partial.
 *  - Whether an actual model ran is read from `AgentRuntimeCounters`, not asserted.
 *
 * ## What is v6 about it
 *
 * The record carries everything a v5 record carried — every dispatched call with its arguments, the
 * session generation, the detail reads and the target epoch each ran in, the per-argument
 * contact-dependency judgement — plus the two things v5 could not answer: which of the four states
 * `expected_slots` was declared in for each turn, and the session state each scenario opened with.
 * Without the first, a reader cannot check its own slot classification against the dataset, which is
 * how a JGA of 223/258 stood beside an authoritative 223/225 with nothing noticing. Without the
 * second, `session_reset_correctness` falls back to a predicate weaker than the scorer's own.
 *
 * Four host readers recompute every official metric from this record, and the run's validity is a
 * property of their agreement, not of any one of them.
 *
 * RUN_D5 was never executed — v5 ended `HOLD BEFORE DEVICE PREFLIGHT` before any device was
 * connected — so there is no earlier device run to supersede, and `ryeong_device_eval_v5_official`
 * stays an empty namespace that a v8 run is refused by name.
 *
 * Opt-in: without `-e ryeongDeviceRunV8 true` this reports as skipped.
 */
@RunWith(AndroidJUnit4::class)
class RyeongDeviceEvaluationV8Test {

    private val args = InstrumentationRegistry.getArguments()
    private val enabled = args.getString("ryeongDeviceRunV8") == "true"

    /**
     * Read only so it can be refused.
     *
     * Ignoring the argument would let an operator believe a cap had been applied; accepting it would
     * produce a five-scenario file wearing RUN_D8's name. Failing loudly is the only option that
     * leaves no ambiguity.
     */
    private val scenarioLimit = args.getString("ryeongScenarioLimit")?.toIntOrNull() ?: 0

    @Test
    fun ryeongOfficialRunD8OnDevice() {
        if (!enabled) {
            android.util.Log.i(TAG, "skipped: pass -e ryeongDeviceRunV8 true to run")
            return
        }
        val context = ApplicationProvider.getApplicationContext<android.content.Context>()

        // Before anything else, and before the invocation is claimed.
        DeviceRunEvidenceV8.requireScenarioLimitAllowed(
            DeviceRunEvidenceV8.RunMode.OFFICIAL, scenarioLimit,
        )

        val outcome = RyeongDeviceRunnerV8(
            context, DeviceRunEvidenceV8.RunMode.OFFICIAL, scenarioLimit = 0,
        ).run()

        val paths = DeviceRunEvidenceV8.Paths(
            context.getExternalFilesDir(null) ?: context.filesDir,
            DeviceRunEvidenceV8.RunMode.OFFICIAL,
        )
        android.util.Log.i(TAG, "RUN_D8 turns=${outcome.turnsRun} " +
            "validity=${outcome.validityFailures} promotion=${outcome.promotionFailures} " +
            "contact_findings=${outcome.contactDependencyFindings}")

        // Asserted after the evidence is on disk, so a failure still leaves a record to read.
        assertEquals(
            "official invocations", 1,
            DeviceRunEvidenceV8.OfficialRunGuard.invocationCount(paths),
        )
        assertEquals("promotion failures", emptyList<String>(), outcome.promotionFailures)
        assertEquals("partial files remaining after a complete run", emptyList<String>(), paths.stalePartials())
        assertEquals("turns", RyeongDeviceRunnerV8.EXPECTED_TURNS, outcome.turnsRun)
        assertEquals("scenarios", RyeongDeviceRunnerV8.EXPECTED_SCENARIOS, outcome.scenariosRun)
        assertEquals("cross-scenario leakage", 0, outcome.crossScenarioLeakage)
        assertEquals("observation disagreement", 0, outcome.observationDisagreements)
        assertTrue(
            "an actual-model evaluation recorded no actual model invocation",
            outcome.counters.actualModelExecuted,
        )
        assertEquals("validity failures", emptyList<String>(), outcome.validityFailures)
    }

    private companion object {
        const val TAG = "RyeongDeviceEvalV8"
    }
}
